        ))}
        {GRADES.map((g) => (
          <span key={`proof-${g}`}>{field(`proof-threshold-${g}`, `Proof threshold grade ${g}`)} </span>
        ))}
        {GRADES.map((g) => (
          <span key={`clerk-limit-${g}`}>{field(`clerk-limit-${g}`, `Clerk limit grade ${g}`)} </span>
